BEGIN TRANSACTION READ ONLY; SET LOCAL statement_timeout = '20s'; SELECT jsonb_build_object('collected_at',current_timestamp,'transaction_read_only',current_setting('transaction_read_only'),'application_schemas',(SELECT COALESCE(jsonb_agg(nspname ORDER BY nspname),'[]'::jsonb) FROM pg_namespace WHERE nspname IN ('public','app')),'application_relations',(SELECT COALESCE(jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind)),'[]'::jsonb) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('public','app') AND c.relkind IN ('r','p','v','m','S','f')),'prisma_ledger',to_regclass('public._prisma_migrations')::text,'public_default_privileges',(SELECT COALESCE(jsonb_agg(jsonb_build_object('creator',pg_get_userbyid(d.defaclrole),'kind',d.defaclobjtype,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) ORDER BY d.defaclrole,d.defaclobjtype,a.grantee,a.privilege_type),'[]'::jsonb) FROM pg_default_acl d JOIN pg_namespace n ON n.oid=d.defaclnamespace CROSS JOIN LATERAL aclexplode(d.defaclacl) a WHERE n.nspname='public'),'public_functions',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',p.proname,'return_type',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'definition',pg_get_functiondef(p.oid))),'[]'::jsonb) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.prokind='f'),'event_triggers',(SELECT COALESCE(jsonb_agg(jsonb_build_object('name',evtname,'event',evtevent,'enabled',evtenabled,'function',evtfoid::regprocedure::text,'tags',evttags)),'[]'::jsonb) FROM pg_event_trigger),'data_api_database_settings',(SELECT COALESCE(jsonb_agg(jsonb_build_object('database',d.datname,'role',COALESCE(r.rolname,'ALL'),'setting',s.setting)),'[]'::jsonb) FROM pg_db_role_setting dr LEFT JOIN pg_database d ON d.oid=dr.setdatabase LEFT JOIN pg_roles r ON r.oid=dr.setrole CROSS JOIN LATERAL unnest(dr.setconfig) s(setting) WHERE s.setting LIKE 'pgrst.db_schemas=%' OR s.setting LIKE 'pgrst.db_extra_search_path=%')) AS fresh_target_review; ROLLBACK;
